#include <iostream>
#include <vector>
#include <memory>
#include <algorithm>
using namespace std;

int main() {
    auto data = make_unique<vector<int>>(vector<int>{3, 1, 4, 1, 5});
    sort(data->begin(), data->end());
    for (int n : *data) {
        cout << n << " ";
    }
    return 0;
}
